<script setup lang="ts">
import {ref,onMounted,watch} from 'vue';import {useStudies} from '../stores/studies';import {useSamples} from '../stores/samples';import {useAuth} from '../stores/auth';import {useTask} from '../hooks/useTask';import {metrics,directions} from '../constants/enums';import {num} from '../utils/format';import type {Sample,Criterion,MetricCode} from '../types/domain';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';import StudySelect from '../components/StudySelect.vue';const study=useStudies(),samples=useSamples(),auth=useAuth(),{error,busy,perform}=useTask(),tab=ref('samples'),ids=ref<number[]>([]),editSample=ref<Sample|null>(null),editCriterion=ref<Criterion|null>(null),message=ref('');const codes=Object.keys(metrics) as MetricCode[];onMounted(()=>perform(async()=>{await study.load();await Promise.all([samples.load(),study.loadCriteria()]);ids.value=[...(study.current?.material_ids||[])]}));watch(()=>study.selected,()=>{ids.value=[...(study.current?.material_ids||[])];editCriterion.value=null;editSample.value=null;message.value=''});async function saveSelection(){if(!study.current)return;await study.save({...study.current,material_ids:ids.value},study.current.id);message.value='候选集合已保存；现有结果快照不会被改写。'}async function saveSample(e:Event){const d=new FormData(e.target as HTMLFormElement),data:Record<string,unknown>=Object.fromEntries(d);codes.forEach(k=>data[k]=Number(d.get(k)));await samples.save(data,editSample.value?.id);editSample.value=null;message.value='试样已保存到全局资料库；新试样需勾选并保存候选集合。'}async function saveCriterion(e:Event){const d=new FormData(e.target as HTMLFormElement);await study.saveCriterion({...Object.fromEntries(d),study_id:study.selected,center_weight:Number(d.get('center_weight'))},editCriterion.value?.id);editCriterion.value=null;message.value='指标口径已保存；后续新任务使用更新值。'}
</script><template><PageHeading no="02" title="试样与口径" sub="材料保留原始单位；方向、候选集合与中心权重都要先说清楚。"/><StudySelect/><ErrorNotice :error="error"/><p v-if="message" class="success" role="status">{{message}}</p><div class="data-tabs"><button :class="{active:tab==='samples'}" @click="tab='samples'">材料资料 / {{samples.items.length}}</button><button :class="{active:tab==='criteria'}" @click="tab='criteria'">指标口径 / {{study.criteria.length}}</button></div><section v-if="tab==='samples'"><div class="section-line"><h2>机构试样资料库</h2><div class="selection-actions"><span>已勾选 {{ids.length}} / {{samples.items.length}} 份</span><button v-if="auth.canEdit" @click="perform(saveSelection)" :disabled="busy">保存候选集合</button></div></div><p class="muted">资料库由三套研究共享；原始测量修改会影响后续研究，已经排队的快照保持原样。</p><details v-if="auth.canEdit" class="edit-fold" :open="!!editSample"><summary>{{editSample?'编辑 '+editSample.code:'＋ 登记材料试样'}}</summary><form :key="editSample?.id||'new'" class="form-grid sample-form" @submit.prevent="e=>perform(()=>saveSample(e))"><label>试样编号<input name="code" :value="editSample?.code" required minLength="2"/></label><label>试样名称<input name="name" :value="editSample?.name" required minLength="2"/></label><label>材料类别<input name="family" :value="editSample?.family" required/></label><label>批次<input name="batch" :value="editSample?.batch"/></label><label v-for="key in codes" :key="key">{{metrics[key].name}} / {{metrics[key].unit}}<input :name="key" type="number" step="any" min="0" :max="key==='absorption'?1:key==='price'?10000:1000" :value="editSample?.[key]||0" required/></label><div class="button-row"><button class="primary" :disabled="busy">保存试样</button><button v-if="editSample" type="button" @click="editSample=null">取消编辑</button></div></form></details><div class="table-scroll"><table class="sample-table"><thead><tr><th>候选</th><th>试样 / 类别</th><th v-for="key in codes" :key="key">{{metrics[key].name}}<small>{{metrics[key].unit}}</small></th><th v-if="auth.canEdit"/></tr></thead><tbody><tr v-for="s in samples.items" :key="s.id"><td><input v-model="ids" type="checkbox" :value="s.id" :disabled="!auth.canEdit" :aria-label="'纳入'+s.code"/></td><td><b>{{s.code}} · {{s.name}}</b><small>{{s.family}} / {{s.batch}}</small></td><td v-for="key in codes" :key="key">{{num(s[key],key==='absorption'?4:3)}}</td><td v-if="auth.canEdit"><button class="small-button" @click="editSample=s">编辑</button></td></tr></tbody></table></div><p v-if="!samples.items.length" class="empty">先登记至少两份材料试样，再勾选到研究中。</p></section><section v-else class="criterion-spread"><div><h2 class="ruled-title">指标方向与原始中心权重</h2><article class="criterion-row" v-for="c in study.criteria" :key="c.id"><div><small>{{c.code}} / {{c.unit}}</small><h3>{{c.name}}</h3></div><span :class="['direction',c.direction]">{{directions[c.direction]}}</span><b>{{c.center_weight}}</b><button v-if="auth.canEdit" class="small-button" @click="editCriterion=c">编辑</button></article><p v-if="!study.criteria.length" class="empty">本研究还未登记指标。从右侧定义至少一项方向与正中心权重。</p><aside class="margin-note"><b>零列与常量列</b><p>零范数列保留为零；非零常量列仍标准化，但不贡献候选间距离。权重保留，不偷偷分配到其他列。结果会逐列记录处理口径。</p><p>候选增删与指标平移可能改变TOPSIS排名。只有正比例换单位在数值精度范围内保持结果。</p></aside></div><form v-if="auth.canEdit" :key="editCriterion?.id||'new'" @submit.prevent="e=>perform(()=>saveCriterion(e))"><h2>{{editCriterion?'编辑指标':'登记指标口径'}}</h2><label>指标<select name="code" :value="editCriterion?.code||'absorption'"><option v-for="key in codes" :key="key" :value="key">{{metrics[key].name}} / {{key}}</option></select></label><label>显示名称<input name="name" :value="editCriterion?.name||'吸声系数'" required/></label><label>单位<input name="unit" :value="editCriterion?.unit||'αw'" required/></label><label>方向<select name="direction" :value="editCriterion?.direction||'benefit'"><option value="benefit">越大越优 / benefit</option><option value="cost">越小越优 / cost</option></select></label><label>原始中心权重<input name="center_weight" type="number" step="any" min="0" max="1000" :value="editCriterion?.center_weight||1" required/></label><button class="primary" :disabled="busy">保存口径</button><button v-if="editCriterion" type="button" @click="editCriterion=null">取消</button></form></section></template>